//Make these bool so that the actual test assert returns what lines.
inline bool compare_vector(const std::array<float,3>& TruthVec, const Vector3f& TestVec, float tol, char* msg) {
  msg[0] = '\0'; //Clear previous msg
  for (size_t i = 0; i < 3; ++i) {
      if (std::fabs(TruthVec[i] - TestVec[i]) > tol) {
          std::snprintf(msg, 100,
                        "Vector mismatch at index %u: expected %.9f, got %.9f",
                          i, TruthVec[i], TestVec[i]);
          return false;
      }
  }
  return true;
}


inline bool compare_quaternion(const std::array<float, 4>& TruthQuat,
                               const Quaternion& TestQuat,
                               float tol,
                               char* msg) {
                                
    std::array<float, 4> test = {TestQuat.w(), TestQuat.x(), TestQuat.y(), TestQuat.z()};

    msg[0] = '\0'; //Clear previous msg
    for (size_t i = 0; i < 4; ++i) {
        float diff = std::fabs(TruthQuat[i] - test[i]);
        if (diff > tol) {
            std::snprintf(msg, 100,
                          "Quaternion mismatch at index %u: expected %.9f, got %.9f",
                           i, TruthQuat[i], test[i]);
            return false;
        }
    }
    
    return true;
}


inline bool compare_matrix(const Matrix18f& TruthMatrix, const Matrix18f& TestMatrix, float tol,char* msg) {
  // Compare covariance
  msg[0] = '\0'; //Clear previous msg

  for (unsigned int i = 0; i<324; i++ ){
    if (fabs(TruthMatrix[i] - TestMatrix[i]) > tol) {
        snprintf(msg, 100, 
                  "Matrix mismatch at index %u: expected %.9f, got %.9f", 
                  i, TruthMatrix[i], TestMatrix[i]);
        return false; 
    }
  }

  return true;
}

// // Individual test functions
void test_init() {
  TEST_ASSERT_FLOAT_WITHIN(tol, sig_acc, ESKFBias.getSigAcc());
  TEST_ASSERT_FLOAT_WITHIN(tol, sig_gyro, ESKFBias.getSigGyro());
  TEST_ASSERT_FLOAT_WITHIN(tol, eta_acc, ESKFBias.getEtaAcc());
  TEST_ASSERT_FLOAT_WITHIN(tol, eta_gyro, ESKFBias.getEtaGyro());
  TEST_ASSERT_FLOAT_WITHIN(tol, eta_mag, ESKFBias.getEtaMag());

  TEST_ASSERT_FLOAT_WITHIN(tol, sig_mag, ESKFBias.getSigMag());
  TEST_ASSERT_FLOAT_WITHIN(tol, sig_tilt, ESKFBias.getSigTilt());
  TEST_ASSERT_FLOAT_WITHIN(tol, sig_alt, ESKFBias.getSigAlt());
  TEST_ASSERT_FLOAT_WITHIN(tol, sig_gps_pos, ESKFBias.getSigGPSPos());
  TEST_ASSERT_FLOAT_WITHIN(tol, sig_gps_vel, ESKFBias.getSigGPSVel());

  // Compare covariance
  Matrix18f testP0 = ESKFBias.getCovariance();

  char msg [100];
  bool P0_test_result = compare_matrix(P0, testP0, tol, msg);
  TEST_ASSERT_TRUE_MESSAGE(P0_test_result, msg);

  
  
}



