  pos_test_result = compare_vector(pos_true,pos_est, tol, msg);
  TEST_ASSERT_TRUE_MESSAGE(pos_test_result, msg);

  vel_test_result = compare_vector(vel_true,vel_est, tol,msg);
  TEST_ASSERT_TRUE_MESSAGE(vel_test_result, msg);

  quat_test_result = compare_quaternion(quat_true, quat_est, tol,msg);
  TEST_ASSERT_TRUE_MESSAGE(quat_test_result, msg);

  rates_test_result = compare_vector(rates_true,rates_est, tol,msg);
  TEST_ASSERT_TRUE_MESSAGE(rates_test_result, msg);

  biasAccel_test_result = compare_vector(biasAccel_true,biasAccel_est, tol,msg);
  TEST_ASSERT_TRUE_MESSAGE(biasAccel_test_result, msg);

  biasGyro_test_result = compare_vector(biasGyro_true,biasGyro_est, tol,msg);
  TEST_ASSERT_TRUE_MESSAGE(biasGyro_test_result, msg);

  biasMag_test_result = compare_vector(biasMag_true,biasMag_est, tol,msg);
  TEST_ASSERT_TRUE_MESSAGE(biasMag_test_result, msg);

  covariance_test_result = compare_matrix(P_true, P_est, tol, msg);
  TEST_ASSERT_TRUE_MESSAGE(covariance_test_result, msg);



